  insert into public.brands (name, website, description, country, status) values ('SEW-WHAT?', 'https://sewwhatvirginhair.com', 'Premium virgin-hair brand running its own SEW-WHAT? Creator Program on its own site: creators earn 10% commission on every sale through a unique referral link and personal discount code, paid monthly via PayPal, and the program page states twice that there is no cap on earnings. Creators must post at least twice a month; 5,000+ followers is preferred but micro-creators with strong engagement are accepted.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct (SEW-WHAT? Creator Program)', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://sewwhatvirginhair.com/pages/sew-what-creator-program.', 'https://sewwhatvirginhair.com/pages/sew-what-creator-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'SEW-WHAT? Creator Program', 'https://sewwhatvirginhair.com/pages/sew-what-creator-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://sewwhatvirginhair.com/pages/sew-what-creator-program', 'brand_site', 'affiliate_program', 'SEW-WHAT?''s own Creator Program page recruits beauty, hair and lifestyle content creators (stylists/salon owners are also welcomed, but the program is creator-first with Instagram/TikTok/YouTube/blog content expectations), gives each approved creator a unique referral link, a personal discount code and a creator dashboard, and requires at least 2 posts per month; 5,000+ followers is preferred, with micro-creators accepted on engagement.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://sewwhatvirginhair.com/pages/sew-what-creator-program', 'brand_site', 'commission_rate', 'The brand''s own page publishes the commission structure: ''Earn 10% commission on every sale'', monthly payouts via PayPal on the 1st of the month for the previous month''s approved sales, plus performance-based bonuses.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://sewwhatvirginhair.com/pages/sew-what-creator-program', 'brand_site', 'commission_cap', 'The brand''s own page states the earnings cap explicitly twice: ''No earning cap'' in the commission structure list and ''There is no cap on earnings - the more you promote, the more you earn'' in the program detail, so commission_cap is recorded as uncapped. No absolute creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 18, 17, 7, 7, 3, '{"niche_fit": "Premium virgin hair is highly visual, tutorial-friendly material for hair and beauty creators, though narrower than skincare or makeup.", "ugc_evidence": "A creator-native program: referral links, personal codes, a creator dashboard, defined monthly content expectations across Instagram, TikTok, YouTube and blogs, and social feature opportunities.", "compensation": "Clean 10% on every sale with an explicit no-cap statement on the brand''s own page - verified uncapped - plus performance bonuses.", "contact_access": "Application and dashboard are on the brand''s own site; no public program email is published.", "opportunity_availability": "Open application; 5,000+ followers preferred but micro-creators with strong engagement are accepted; a 2-posts-per-month commitment is required.", "credibility": "Smaller specialist brand; program terms are fully published on its own site, but scale and track record are modest."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Glo Skin Beauty', 'https://www.gloskinbeauty.com', 'Pro-heritage mineral makeup and skincare brand whose own affiliate page splits the program in two: an Influencer route for influencers, publishers and fans with a social following, paying 10% commission on all new consumer orders, and a separate Professional route for existing trade accounts. The influencer program runs through Refersion, whose terms confirm the standard non-professional payout at 10% for new customers (1% for past purchasers).', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Refersion', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.gloskinbeauty.com/pages/glo-affiliate-program.', 'https://www.gloskinbeauty.com/pages/glo-affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Glo Skin Beauty Affiliate Program - Influencer Route (Refersion)', 'https://www.gloskinbeauty.com/pages/glo-affiliate-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.gloskinbeauty.com/pages/glo-affiliate-program', 'brand_site', 'affiliate_program', 'Glo Skin Beauty''s own affiliate page offers two routes: ''For Influencers'' - only for influencers, publishers and other fans of the brand with a social following - paying 10% commission on all new consumer orders with ongoing commission on associated customers; and ''For Professional Accounts'' - only for current professional trade accounts - at 15%. Selected influencers earn on all net sales and receive free products monthly. Only the influencer route is recorded here; the professional route is a trade program.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://glopartners.refersion.com/?oid=102564&cs=2db8ddc5e2a7e035c8838043a0c50d3b10f564069ef722805b1528892dc3a8a1', 'affiliate_network', 'commission_rate', 'The program''s Refersion terms publish the Default Standard Payout (non-professional) at 10% commission for new customers and 1% for past purchasers/existing customers on MSRP orders, with a 30-day attribution window - matching the 10% influencer rate on the brand''s page, which is the rate recorded. The same terms show a 20%/15% tier tied to keeping a Professional account active; that is the trade route and is not the creator rate. No earnings-cap statement or absolute creator counts are published, so cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 15, 7, 7, 5, '{"niche_fit": "Mineral makeup plus clinical skincare from a pro-heritage brand - strong tutorial, complexion and routine UGC material.", "ugc_evidence": "A dedicated influencer route on the brand''s own page, explicitly for social followings, with free product for selected creators and Refersion tracking behind it.", "compensation": "10% on new consumer orders is clean and confirmed in both the brand page and the Refersion terms; repeat-customer payout drops to 1% for non-professionals, and no uncapped statement is published.", "contact_access": "Application is on the brand''s own domain with a 48-hour follow-up promise if interested; no public program email is published.", "opportunity_availability": "Selective - the brand follows up only if interested - and the influencer route requires a social following.", "credibility": "Established professional beauty brand with complete, consistent terms published in two places (brand page and Refersion)."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Shankara', 'https://shankara.com', 'Ayurvedic skincare brand (100% natural, cruelty-free; 100% of net profits support humanitarian initiatives) whose own affiliate page offers commission starting at 10% on every purchase made through an affiliate''s link and code, with bonuses for high performers, free products and samples, exclusive audience discount codes and dedicated support; payments run through the affiliate network (the page names Awin as the example) and tracking uses a 30-day cookie.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://shankara.com/pages/affiliate.', 'https://shankara.com/pages/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Shankara Affiliate Program (Awin)', 'https://shankara.com/pages/affiliate', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shankara.com/pages/affiliate', 'brand_site', 'affiliate_program', 'Shankara''s own affiliate page states affiliates earn ''commission starting at 10% on every purchase made through your link and code'', with bonuses and perks for high performers, free products and samples, exclusive discount codes, early access to launches and dedicated affiliate support; the application includes a brand education course and a 1:1 expert consultation, and there is no strict minimum sales requirement.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shankara.com/pages/affiliate', 'brand_site', 'commission_rate', 'The brand''s FAQ states sales are tracked through unique links on a 30-day cookie window and ''Payments are processed through the affiliate network (e.g., Awin) via methods like BACS or wire transfer'', with schedule and thresholds set by the network - so the network is recorded as Awin per the brand''s own wording. The recorded 10% is the published starting rate. The page publishes no earnings-cap statement and no creator counts, so cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 14, 8, 7, 4, '{"niche_fit": "Ayurvedic, natural skincare with a strong ritual and ingredients story - good routine and wellness-led UGC material.", "ugc_evidence": "Brand-run affiliate page with link-and-code tracking, audience discount codes, free products and samples, and dedicated affiliate support.", "compensation": "Published starting rate of 10% with performance bonuses; the page does not publish the top of the range or any cap statement, so cap stays unknown.", "contact_access": "Full program page and FAQ on the brand''s own domain; support is offered to affiliates, though no public program email is published.", "opportunity_availability": "Open application with no strict minimum sales requirement; onboarding includes a required education course and consultation.", "credibility": "Established Ayurvedic brand with a stated humanitarian profit model and complete program terms on its own site."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Cult Beauty', 'https://www.cultbeauty.co.uk', 'UK-born prestige beauty retailer (THG) running its Global Affiliate Programme on Awin: the Awin rate card pays Content publishers 10% on new-customer sales and 5% on existing, with dedicated UGC & Communities (2%) and Influencer (1%) tiers; the profile notes influencers are managed in-house rather than through Awin and publishes influencer@cultbeauty.co.uk for partnership discussions.', 'United Kingdom', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'influencer@cultbeauty.co.uk', null, null, 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/29063?setLocale=pl_PL.', 'https://ui.awin.com/merchant-profile/29063?setLocale=pl_PL', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Cult Beauty Global Affiliate Programme (Awin)', 'https://ui.awin.com/merchant-profile/29063?setLocale=pl_PL', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/29063?setLocale=pl_PL', 'affiliate_network', 'affiliate_program', 'Cult Beauty''s Awin Global profile describes a curated prestige beauty retailer with a 30-day cookie, app tracking, a dedicated in-house affiliate team, weekly exclusive offers and product sampling opportunities; it also states ''Cult Beauty does not work with influencers via the Awin affiliate channel, as this is managed in-house'' and publishes influencer@cultbeauty.co.uk for influencer partnerships.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/29063/commission-groups?setLocale=de_DE', 'affiliate_network', 'commission_rate', 'The Awin commission-groups page publishes CPA by publisher type: Content 10% new customer / 5% existing, Shopping Directory 10%/5%, UGC & Communities 2%/2%, Influencer 1%/1%, with exclusions (0% gift cards, 1% electricals and selected brands, 2% advent calendars). The recorded 10% is the Content new-customer rate - the main creator-publisher tier on the network. No earnings-cap statement or absolute creator counts are published, so cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 15, 14, 12, 8, 5, '{"niche_fit": "A huge prestige and indie catalogue in one basket - ideal for discovery, haul and hero-product UGC.", "ugc_evidence": "Awin programme with a dedicated UGC & Communities tier and an in-house influencer team; note the dedicated UGC network rate is only 2%, with the stronger 10% paid to Content publishers.", "compensation": "10% new-customer rate for content publishers (5% existing) is solid for a retailer; UGC and influencer network tiers are much lower, and no cap statement is published.", "contact_access": "Published influencer partnership email on the Awin profile plus a dedicated in-house affiliate team.", "opportunity_availability": "Open Awin application for publishers; influencer partnerships are application-by-email to the in-house team.", "credibility": "Long-established UK prestige retailer (THG-owned) with a complete published Awin rate card."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Clinique', 'https://www.clinique.co.uk', 'Estée Lauder''s dermatologist-developed, allergy-tested, fragrance-free skincare and makeup brand. Network listings record its affiliate program on Rakuten Advertising, but published rate figures conflict across current sources (6% per LinkClicky, 7-10% per Brandid, up to 6% per LinkApprove, 1.5% per Shopper), so no single rate is recorded.', 'United States', 'published') returning id into bid;
