  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/clinique/', 'affiliate_network', 'affiliate_program', 'LinkClicky''s program listing records Clinique''s affiliate platform as Rakuten Advertising with a 6% per-sale commission for CA/GB regions; the brand does not publish an affiliate page of its own in the sources found, so the route is network-reported.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://brandid.app/blog/best-beauty-affiliate-programs/', 'directory', 'commission_rate', 'Published rate figures conflict: Brandid''s 2026 guide lists Clinique at 7-10% with a 30-day cookie via Estée Lauder networks, LinkApprove lists up to 6%, LinkClicky lists 6%, and Shopper lists 1.5% - no settleable single rate, so commission_rate is null with the conflict documented. No earnings-cap statement or absolute creator counts are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 13, 9, 6, 7, 5, '{"niche_fit": "Iconic dermatologist-developed skincare with universal recognition - among the strongest routine and sensitive-skin content fits available.", "ugc_evidence": "Affiliate route exists via Rakuten, but the brand publishes no creator program page of its own and listings describe selective approval for quality sites.", "compensation": "Directories conflict between 1.5%, 6% and 7-10%, so no rate is recorded; that uncertainty caps the compensation score.", "contact_access": "No published program email was found; contact runs through Rakuten after application.", "opportunity_availability": "Network application via Rakuten; approval is described as selective in current guides.", "credibility": "Est\u00e9e Lauder flagship brand founded in 1968; the affiliate facts are network-reported rather than brand-published, which is noted in the evidence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('e.l.f. Cosmetics', 'https://www.elfcosmetics.com', 'Mass-market vegan, cruelty-free makeup and skincare brand (e.l.f. Beauty, Oakland CA) whose affiliate program runs on Rakuten Advertising (CID 39724 per a network listing). Published rate figures conflict across current sources (5% per LinkClicky, 2-5% per HiEnergy''s Rakuten listing, 5-12% network-dependent per Brandid and Clickwire), so no single rate is recorded.', 'United States', 'published') returning id into bid;
