  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://brandid.app/blog/best-beauty-affiliate-programs/', 'directory', 'commission_rate', 'Published rate figures conflict by network and source: Brandid lists 5-12% depending on network, HiEnergy''s Rakuten listing lists 2-5%, and LinkClicky lists 5% - no settleable single rate, so commission_rate is null with the conflict documented. No earnings-cap statement or absolute creator counts are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 14, 9, 6, 8, 5, '{"niche_fit": "Gen-Z favourite mass beauty brand - dupe, budget and viral-product content is some of the highest-converting UGC in the category.", "ugc_evidence": "Affiliate program on a major network (Rakuten) for a social-first brand; the brand publishes no creator program page of its own in the sources found.", "compensation": "No settleable published rate - figures range from 2-5% to 5-12% depending on source and network - so no rate is recorded; cap unknown.", "contact_access": "No published program email was found; contact runs through Rakuten after application.", "opportunity_availability": "Open network application through Rakuten (also listed on Sovrn/Skimlinks-type aggregators).", "credibility": "Major public US beauty company with global retail distribution; affiliate terms are network-reported only."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('L''Occitane', 'https://ie.loccitane.com', 'French Provence beauty house (founded 1976) whose own affiliate programme page (Irish storefront) offers free signup, real-time tracking and ''up to 10% commission'' on uk.loccitane.com sales within a 30-day cookie, with applications routed to Impact and management by Silverbean. ''Up to 10%'' is a ceiling and a CJ listing elsewhere claims 2.5%, so no single rate is recorded.', 'France', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ie.loccitane.com/affiliate-programme.', 'https://ie.loccitane.com/affiliate-programme', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'L''Occitane Affiliate Programme (Impact)', 'https://ie.loccitane.com/affiliate-programme', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ie.loccitane.com/affiliate-programme', 'brand_site', 'affiliate_program', 'L''Occitane''s own affiliate programme page states signup is free, affiliates get campaign newsletters, real-time reporting and sales tracking, a product feed and collaboration opportunities, and applications go through Impact (''Click here to apply'' routes to app.impact.com) with a dedicated management team at Silverbean.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ie.loccitane.com/affiliate-programme', 'brand_site', 'commission_rate', 'The brand''s page publishes only a ceiling - ''Earn up to 10% commission on all sales on uk.loccitane.com within a 30-day cookie window'' - while LinkClicky lists the program on CJ Affiliate at 2.5% per sale; a ceiling plus a conflicting network figure is not a settleable rate, so commission_rate is null. No earnings-cap statement or absolute creator counts are published, so cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ie.loccitane.com/affiliate-programme', 'brand_site', 'contact', 'The affiliate page''s contact link for its management team resolves through a staging subdomain (staging-eu01-loccitane.demandware.net), so no affiliate-team email is recorded as a contact; this needs review against a live-domain source before use.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 9, 7, 7, 5, '{"niche_fit": "Premium natural skincare, body and fragrance with strong gifting and ritual content angles.", "ugc_evidence": "Brand-run affiliate programme page feeding Impact, with collaboration opportunities named; pitched at publishers generally rather than social creators specifically.", "compensation": "Only an ''up to 10%'' ceiling is brand-published and a 2.5% CJ figure conflicts, so no rate is recorded; cap unknown.", "contact_access": "Programme page on the brand''s own domain with a named management agency (Silverbean); the page''s team email link resolves via a staging subdomain, so no email is recorded.", "opportunity_availability": "Free, open application through Impact from the brand''s page.", "credibility": "Global French beauty house founded in 1976 with its programme on a major network and agency management."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('JLo Beauty', 'https://jlobeauty.com', 'Jennifer Lopez''s skincare brand, whose own affiliates page routes signups to Rakuten (LinkShare) and promises commissions, exclusive affiliate offers and social feature opportunities for tagging the brand - but publishes no commission percentage. A single third-party guide claims 21% via Impact, which conflicts with the Rakuten route recorded by both the brand page and FMTC (Rakuten #53046), so no rate is recorded.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Rakuten Advertising', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://jlobeauty.com/pages/affiliates.', 'https://jlobeauty.com/pages/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'JLo Beauty Affiliate Program (Rakuten Advertising)', 'https://jlobeauty.com/pages/affiliates', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://jlobeauty.com/pages/affiliates', 'brand_site', 'affiliate_program', 'JLo Beauty''s own affiliates page states affiliates earn commissions sharing products across website or social channels with unique affiliate links, get exclusive offers and promotions, and can be featured by tagging the brand on Instagram and TikTok; signup is explicitly ''Sign Up for your Rakuten Account'' with LinkShare sign-in links.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.fmtc.co/new-fmtc-merchants-include-foreo-hamilton-watch-jlo-beauty-trivago-wonderbly/', 'affiliate_network', 'commission_rate', 'FMTC''s merchant listing independently records JLO Beauty on Rakuten Advertising (#53046, Health & Beauty). The brand''s page publishes no rate; a 2026 guide (Brandid) claims 21% via Impact, which conflicts with the Rakuten route on both brand and FMTC sources, so commission_rate is null with the conflict documented. No earnings-cap statement or absolute creator counts are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 9, 6, 8, 4, '{"niche_fit": "Celebrity glow skincare with premium price points - strong routine and results-led UGC angles.", "ugc_evidence": "Brand-run affiliates page pitched directly at social sharing, with a social-feature incentive for tagging the brand on Instagram and TikTok.", "compensation": "No brand-published rate, and the single 21% third-party claim conflicts with the verified Rakuten route, so no rate is recorded; cap unknown.", "contact_access": "Program page on the brand''s own domain with Rakuten signup routes; no public program email is published.", "opportunity_availability": "Open signup through Rakuten from the brand''s page.", "credibility": "Well-known celebrity-founded brand on a major network; the rate conflict is documented honestly in the evidence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Tata Harper', 'https://www.tataharperskincare.com', 'Vermont farm-to-face luxury clean skincare brand whose affiliate program is listed on FlexOffers at 16% of sales from new customers (8% existing) with a 30-day cookie - but other current listings conflict sharply (around 7-10% in a 2026 guide, 3.2% on Shopper, 1-4% on InfluencerRate), so no single rate is recorded.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'FlexOffers', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.flexoffers.com/affiliate-programs/tata-harper-affiliate-program/.', 'https://www.flexoffers.com/affiliate-programs/tata-harper-affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Tata Harper Affiliate Program (FlexOffers)', 'https://www.flexoffers.com/affiliate-programs/tata-harper-affiliate-program/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flexoffers.com/affiliate-programs/tata-harper-affiliate-program/', 'affiliate_network', 'affiliate_program', 'FlexOffers'' program page (updated 2026-11-18) records the Tata Harper payout as 16% of sales from new customers and 8% for existing customers with a 30-day cookie, a dedicated affiliate management team and application via the brand''s website or social profile.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://brandid.app/blog/best-beauty-affiliate-programs/', 'directory', 'commission_rate', 'Published rate figures conflict sharply: FlexOffers lists 16% new / 8% existing, Brandid''s guide lists around 7-10% via ShareASale, Shopper lists 3.2% and InfluencerRate lists 1-4% - no settleable single rate, so commission_rate is null with the conflict documented. No earnings-cap statement or absolute creator counts are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 9, 6, 7, 5, '{"niche_fit": "Luxury clean skincare made on the brand''s own Vermont farm - premium ingredient and ritual storytelling for UGC.", "ugc_evidence": "Affiliate listings on major networks with a dedicated management team; the brand publishes no creator program page of its own in the sources found.", "compensation": "Published figures range from 1-4% to 16%, so no rate can be recorded; that spread caps the compensation score despite the high FlexOffers figure.", "contact_access": "No published program email was found; contact runs through the network after application.", "opportunity_availability": "Network application via FlexOffers; approval terms are not published.", "credibility": "Established luxury clean-beauty brand sold in 30+ countries; affiliate facts are network-reported, which is noted in the evidence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('RMS Beauty', 'https://www.rmsbeauty.com', 'Clean makeup and skincare brand founded in 2009 by makeup artist Rose-Marie Swift, with its own ''Join the RMS Beauty Affiliate Program'' page on its site. Published rate figures conflict across current sources (a 5-15% range in a 2026 program review, up to 4.2% on Refermate, and network panels ranging from 2.8% to 10.5%), so no single rate is recorded.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct (RMS Beauty Affiliate Program)', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.rmsbeauty.com/pages/affiliate.', 'https://www.rmsbeauty.com/pages/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'RMS Beauty Affiliate Program', 'https://www.rmsbeauty.com/pages/affiliate', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.rmsbeauty.com/pages/affiliate', 'brand_site', 'affiliate_program', 'RMS Beauty''s own site hosts a ''Join the RMS Beauty Affiliate Program'' page, confirming a brand-run affiliate route; the fetched page copy focuses on the founder story and publishes no commission percentage, cookie or cap statement.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliateworldforums.com/threads/rms-beauty-affiliate-program-review.17065/', 'directory', 'commission_rate', 'Published rate figures conflict: a 2026 program review lists a 5-15% range with a 30-day cookie aimed at bloggers, influencers and creators, Refermate lists up to 4.2%, and a network-availability roundup lists RMS panels from 2.8% to 10.5% - no settleable single rate, so commission_rate is null with the conflict documented. No earnings-cap statement or absolute creator counts are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 9, 6, 7, 5, '{"niche_fit": "Pioneer clean-beauty brand with skincare-infused makeup - excellent natural-look tutorial and review material.", "ugc_evidence": "Brand-run affiliate page on its own domain, and program reviews describe it as aimed at beauty bloggers, influencers, makeup artists and content creators.", "compensation": "Published figures conflict from 2.8% up to a 5-15% range, so no rate is recorded; cap unknown.", "contact_access": "Affiliate page on the brand''s own domain; no public program email is published in the sources found.", "opportunity_availability": "Application from the brand''s affiliate page; eligibility terms are not published on the fetched page.", "credibility": "Established clean-beauty pioneer founded in 2009 by a working makeup artist, with wide retail recognition."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('COROS', 'https://coros.com', 'Performance GPS watch brand for endurance athletes — PACE, APEX and NOMAD watches, the DURA solar bike computer and an arm heart-rate monitor, sold through its official US store at coros.com. Its affiliate program runs on AvantLink: the network''s own new-merchant announcement lists COROS at 10% commission with a 30-day cookie, aimed at publishers covering endurance sport.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'AvantLink', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.avantlink.com/new-merchant-advertisers-for-late-march-25/.', 'https://www.avantlink.com/new-merchant-advertisers-for-late-march-25/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'COROS Affiliate Program (AvantLink)', 'https://www.avantlink.com/new-merchant-advertisers-for-late-march-25/', 'https://www.avantlink.com/new-merchant-advertisers-for-late-march-25/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.avantlink.com/new-merchant-advertisers-for-late-march-25/', 'network_announcement', 'affiliate_program', 'AvantLink''s official new-merchant announcement (posted April 1, 2025) lists COROS at ''10% Commission | 30 days Cookie Duration'' and describes it as creating ''performance-focused GPS watches and accessories designed for endurance athletes who demand precision, durability, and cutting-edge training insights''. Publishers sign in to AvantLink to apply. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://yazing.com/affiliate-programs/coros-affiliate-program', 'third_party_directory', 'affiliate_program', 'Yazing''s program listing independently reports the same 10% of sales for the COROS affiliate program, and its COROS pages also reference a brand ambassador & influencer program alongside the affiliate program.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 15, 5, 8, 5, '{"compensation": "A clean 10% confirmed by the network itself on premium-priced GPS watches, with a 30-day cookie; no cap statement is published.", "contact_access": "No partnerships email is published in the fetched sources \u2014 contact is through the AvantLink application.", "credibility": "One of the leading endurance GPS watch brands, with its official US store at coros.com and an industry-leading global warranty.", "niche_fit": "GPS watches are core gear for running, triathlon and trail creators \u2014 training and race content is a natural placement.", "opportunity_availability": "Apply through AvantLink with network sign-in and approval; the program launched on the network in spring 2025.", "ugc_evidence": "Primarily a conventional network affiliate program; a separate ambassador/influencer track is reported by directories but is not documented on a fetched brand page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Brooks Running', 'https://www.brooksrunning.com', 'Performance running footwear and apparel brand creating market-leading running shoes since 1914 (Ghost, Adrenaline GTS, Glycerin and Hyperion lines). Its official affiliate page recruits content and influencer partners through Impact with a 30-day referral window and a dedicated affiliate management team, but publishes no commission rate — and published figures elsewhere conflict, so no rate is recorded.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.brooksrunning.com/en_us/affiliate-program/.', 'https://www.brooksrunning.com/en_us/affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Brooks Affiliate Program (Impact)', 'https://www.brooksrunning.com/en_us/affiliate-program/', 'https://www.brooksrunning.com/en_us/affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.brooksrunning.com/en_us/affiliate-program/', 'official_program_page', 'creator_program', 'Official Brooks affiliate page: ''Sign up is free'', ''Competitive commission rates for content and influencer partners'', ''30-day referral window for content and influencer partners'', and a ''Dedicated affiliate management team''. How it works: ''Apply and create an account with Impact'', drive traffic through provided links, earn commission on purchases within the 30-day window, payment distributed through Impact. The brand publishes no percentage and no earnings-cap statement, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.avantlink.com/new-merchant-advertisers-for-july-2026/', 'network_announcement', 'affiliate_program', 'AvantLink''s new-merchant announcement (posted August 3, 2026) lists Brooks Running as a new AvantLink merchant at 9% commission with a 30-day cookie — a second network listing alongside the Impact route named on the brand''s own page.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/brooks-running/', 'third_party_directory', 'commission_rate_conflict', 'Published rates conflict: Lasso reports 5% per sale, UpPromote''s running roundup reports 1.25% with a 7-day cookie via Impact, and AvantLink''s own announcement lists 9%. Because the brand''s official page publishes no figure and sources conflict across networks, commission_rate is null.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 10, 7, 8, 5, '{"compensation": "The brand publishes no rate and published figures conflict (1.25% / 5% / 9% across sources and networks), so no rate is recorded and compensation scores cautiously; no cap statement is published.", "contact_access": "A dedicated affiliate management team is promised on the official page, but no partnerships email is published.", "credibility": "One of the world''s leading performance running brands, making running shoes since 1914.", "niche_fit": "Running shoes and apparel are core, evergreen content for running and fitness creators \u2014 reviews, rotations and race-day content.", "opportunity_availability": "Free sign-up through Impact from the brand''s affiliate page, with approval notification; a separate Brooks Running Collective creator community also exists.", "ugc_evidence": "The official page explicitly targets ''content and influencer partners'' with a dedicated referral window for them \u2014 clear creator-program evidence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Salomon', 'https://www.salomon.com', 'Outdoor sports brand born in the French Alps in 1947, making footwear, apparel and gear for trail running, hiking, skiing and snowboarding. Its US affiliate page routes partners through Impact with a 30-day cookie and competitive commission on qualified purchases but publishes no rate; its UK Awin profile publishes 5% and explicitly recruits creators and influencers. Published figures conflict by region and network, so no rate is recorded.', 'France', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.salomon.com/en-us/lp/g/affiliates.', 'https://www.salomon.com/en-us/lp/g/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Salomon Affiliate Program (Impact)', 'https://www.salomon.com/en-us/lp/g/affiliates', 'https://www.salomon.com/en-us/lp/g/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.salomon.com/en-us/lp/g/affiliates', 'official_program_page', 'affiliate_program', 'Official Salomon affiliates page: ''By joining the Salomon affiliate program through Impact you can earn commissions on all your favorite products sold through a featured text link or banner on your site.'' Benefits listed: ''Competitive commission on qualified purchases; 30-day cookie window; Full range of text links and banners; High average order value''. No percentage and no earnings-cap statement are published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/86257', 'network_profile', 'creator_program', 'The brand''s UK Awin merchant profile states ''All publishers will receive a commission 5% commission on approved orders'' with a 30-day cookie, and says the program is ''particularly interested in: Creators/Influencers, Bloggers, Sneaker platforms, Lifestyle/fashion platforms, Shopping portals, Editorial Platforms'', with a product feed updated regularly.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/salomon/', 'third_party_directory', 'commission_rate_conflict', 'Directory figures conflict with the brand''s own sources: Lasso reports 10% per sale and names Commission Junction as the network, while FlexOffers reports 4% — against the brand''s own Impact route (US, rate unpublished) and its UK Awin profile at 5%. Because the figures conflict across regions and networks, commission_rate is null.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 10, 5, 8, 5, '{"compensation": "No rate is published on the brand''s own US page and figures conflict by region and network (5% UK Awin / 10% and 4% in directories), so no rate is recorded; no cap statement is published.", "contact_access": "No partnerships email is published in the fetched sources \u2014 joining is through the Impact or Awin applications.", "credibility": "A world-leading mountain-sports brand founded in the French Alps in 1947.", "niche_fit": "Trail running, hiking and snow gear sits at the centre of outdoor, running and winter-sports creator content.", "opportunity_availability": "Open application through Impact (US) or Awin (UK) with brand approval; a valid website or app with relevant content is expected.", "ugc_evidence": "The UK Awin profile explicitly recruits creators and influencers, though the US program page is framed for site publishers with links and banners."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Zwift', 'https://zwift.com', 'Indoor cycling and running training platform — ''the fitness game'' — whose shop sells smart trainers and the Zwift Ride smart bike. Its official partner page pays affiliates 5% of basket value (less tax) on hardware and accessories through Impact, with average order values of $650/£600/€650+, monthly payments and a dedicated in-house affiliate manager; memberships and subscriptions earn no commission, and the program covers only the US, UK and Europe.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://zwift.com/partner-with-zwift.', 'https://zwift.com/partner-with-zwift', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Zwift Affiliate & Partner Program (Impact)', 'https://zwift.com/partner-with-zwift', 'https://zwift.com/partner-with-zwift', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://zwift.com/partner-with-zwift', 'official_program_page', 'affiliate_program', 'Official partner page FAQ: ''Zwift awards affiliates 5% of the basket value, less tax, on most hardware and accessories available from the Zwift shop'' (worked example: 5% of a $1,299.99 Zwift Ride = $64.99). Benefits: commission on all hardware and accessories (US, UK, EU), average order values of $650/£600/€650+, tracked on Impact, monthly payments, dedicated in-house Affiliate Manager. ''At the current time, Zwift only pays commission for hardware and accessories'' — no commission on memberships/subscriptions, and the program is only available where Zwift has an online shop (US, UK, Europe). No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://zwift.com/partner-with-zwift', 'official_program_page', 'creator_program', 'The same official page invites owners of websites, blogs and social channels with ''a passionate audience of cyclists, triathletes, and fitness enthusiasts'', and its FAQ answers ''IS THE AFFILIATE PROGRAM SUITABLE FOR CONTENT CREATORS? Yes! The Zwift affiliate program is a great way to monetize your social media content and help your channel grow.'' Applications are reviewed by a team member after Impact sign-up.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 13, 8, 7, 5, '{"compensation": "A published 5% of basket value on hardware with very high average order values ($650+), so per-sale earnings are substantial; held back because subscriptions \u2014 the product most content promotes \u2014 earn nothing. No cap statement is published.", "contact_access": "A dedicated in-house affiliate manager and a ''speak to us'' contact route are offered on the official page, though no partnerships email is published.", "credibility": "The dominant indoor cycling training platform, with its own hardware line and a global shop.", "niche_fit": "Indoor training hardware and virtual racing are core content for cycling, triathlon and fitness creators.", "opportunity_availability": "Apply via Impact with team review; restricted to the US, UK and Europe, which narrows availability.", "ugc_evidence": "The official FAQ explicitly confirms the program suits content creators and social channels, not just publishers."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Boody', 'https://www.boody.co.uk', 'Sustainable bamboo essentials brand — underwear, basics, lounge and active pieces made from organically grown bamboo, and a member of 1% for the Planet. Its official Social Influencer Program page recruits bloggers, YouTubers and Instagram/Facebook creators, and runs through CommissionFactory at 8% commission on sale value with a 30-day tracking cookie, free to join.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CommissionFactory', 8, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.boody.co.uk/pages/influencer-program.', 'https://www.boody.co.uk/pages/influencer-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Boody Affiliate Program (Social Influencer Program, via CommissionFactory)', 'https://www.boody.co.uk/pages/influencer-program', 'https://www.boody.co.uk/pages/influencer-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.boody.co.uk/pages/influencer-program', 'official_program_page', 'affiliate_program', 'Official Boody influencer program page: ''We work with CommissionFactory, an affiliate network... CommissionFactory tracks all links and orders connected to the affiliate links you post.'' Program overview on the page: ''8% commission on sale value; 30-day tracking cookie period; Datafeed available; Open to custom marketing collaborations; Regular promotions and occasional exclusive offers and incentives.'' Joining is free; applicants apply on the page and are contacted if accepted. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.boody.co.uk/pages/influencer-program', 'official_program_page', 'creator_program', 'The page is explicitly a creator recruitment page: ''Start earning money for your amazing content!... If you have a blog, a YouTube channel or simply keep an engaged Instagram or Facebook page updated, the Boody Affiliate Program could be for you... We''re on the lookout for talented content creators who share our values and want to align with the Boody brand.''', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 13, 4, 8, 4, '{"compensation": "A clean, brand-published 8% on sale value with a 30-day cookie; no cap statement is published.", "contact_access": "No partnerships email is published on the program page \u2014 application is through the page and CommissionFactory.", "credibility": "An established sustainable-essentials brand and 1% for the Planet member, though smaller than the global apparel majors.", "niche_fit": "Bamboo basics, underwear and loungewear are staple try-on, essentials and sustainable-fashion content.", "opportunity_availability": "Free to join via the brand''s page and CommissionFactory, with acceptance confirmed by the brand.", "ugc_evidence": "The program page is written for content creators \u2014 blogs, YouTube channels and engaged Instagram/Facebook pages \u2014 with custom collaboration openness."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Patriot Crew', 'https://patriotcrew.co', 'American-made patriotic apparel brand selling tees and apparel for people ''repping the red, white, and blue''. Its own affiliate page pays 10% commission on all sales with a 60-day cookie and states outright: ''we have no cap on the amount of money you can earn. There is unlimited earning potential here!'' — a verified-uncapped program. Social media influencers can also apply to be brand ambassadors through a published email.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'nick@marketplacevelocity.com', null, 'https://patriotcrew.co/pages/affiliate-program', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://patriotcrew.co/pages/affiliate-program.', 'https://patriotcrew.co/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Patriot Crew Affiliate Program', 'https://patriotcrew.co/pages/affiliate-program', 'https://patriotcrew.co/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://patriotcrew.co/pages/affiliate-program', 'official_program_page', 'commission_cap', 'The brand''s own affiliate page states: ''We pay affiliates a 10% commission on all sales that come in through our website and we have no cap on the amount of money you can earn. There is unlimited earning potential here!'' That is an explicit no-cap earnings statement on the brand''s own page, so commission_cap is uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://patriotcrew.co/pages/affiliate-program', 'official_program_page', 'affiliate_program', 'Program details from the same page: 10% commission on all sales; 60-day cookie life; exclusive affiliate discounts and promotions; a database of creative banners and text links plus a product feed; opportunities to earn bonuses and win prizes. Affiliates are encouraged to promote through social media pages, websites and email databases. Influencers interested in being brand ambassadors are told to email nick@marketplacevelocity.com with their full name, Instagram page link, city/state and shirt size; a phone number (+1 (512) 861 3395) is also published. No affiliate network is named on the page, so the program is recorded as brand direct.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 14, 16, 11, 8, 3, '{"compensation": "10% on all sales with an explicit no-cap statement on the brand''s own page \u2014 verified-uncapped \u2014 plus a long 60-day cookie and bonus/prize opportunities.", "contact_access": "A published email for influencer/ambassador applications (nick@marketplacevelocity.com) and a phone number appear directly on the affiliate page.", "credibility": "A small direct-to-consumer apparel brand; the program terms are clearly published, but the brand itself is niche and little-known next to national labels.", "niche_fit": "Patriotic American-made apparel is a defined niche \u2014 strong for creators in that community, narrower for general fashion audiences.", "opportunity_availability": "Open affiliate sign-up promoted on the brand''s own page, with an additional ambassador application route for influencers.", "ugc_evidence": "The page encourages promotion through social media pages and runs a separate brand-ambassador track for influencers, though it is not a structured UGC campaign program."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Lululemon', 'https://www.lululemon.com', 'Premium athletic apparel brand founded in 1998, designing gear for yoga, running and training. Its Affiliates and Creators program (US and Canada) runs on Awin: the brand''s own Awin merchant profile publishes a 5% default commission rate, a 30-day cookie period and $100+ average order value, and the program offers separate paths for affiliates (websites, blogs, publications) and creators (social media). Reviews commonly report around 7% on most categories, above the published default.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/30347.', 'https://ui.awin.com/merchant-profile/30347', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'lululemon Affiliates and Creators Program (Awin US)', 'https://ui.awin.com/merchant-profile/30347', 'https://ui.awin.com/merchant-profile/30347', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/30347', 'network_profile', 'affiliate_program', 'The brand''s own Awin (US) merchant profile, Program Details: ''5% Default Commission Rate; 30 Day Cookie Period; $100+ AOV'', with categories Clothing, Athletic Clothing, Athletic Gear, athleisure, Women''s clothing, Men''s clothing and Footwear. The recorded 5% is the default rate the brand itself publishes on its network profile. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://reverbico.com/blog/lululemon-affiliate-program/', 'third_party_directory', 'creator_program', 'A detailed program review describes lululemon''s own Affiliates and Creators page as one program with two sign-up paths — affiliates (websites, blogs and publications) and creators (social media) — with the US/Canada Apply button leading to Awin''s publisher sign-up; lululemon does not publish its rate on its own pages, third-party reviews commonly report about 7% with a 30-day cookie, approval is required, and established fitness, wellness or lifestyle content is expected. Regional programs run on other networks outside North America (Rakuten Advertising in several markets, Commission Factory in Australia/New Zealand).', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 17, 12, 5, 6, 5, '{"compensation": "The brand''s own Awin profile publishes a 5% default rate on a $100+ average order value, and reviews commonly report around 7% on most categories \u2014 modest percentages on premium prices; no cap statement is published.", "contact_access": "No partnerships email is published in the fetched sources \u2014 contact is through the Awin application.", "credibility": "One of the world''s most valuable athletic apparel brands, founded in 1998.", "niche_fit": "Athleisure and training apparel are among the most-covered categories in fashion and fitness creator content \u2014 hauls, reviews and everyday outfits.", "opportunity_availability": "Approval-based and selective, limited to the US and Canada on Awin, with an established content presence expected.", "ugc_evidence": "A named Affiliates and Creators program with a dedicated social-creator path alongside the publisher path \u2014 strong, explicit UGC evidence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('BÉIS', 'https://beistravel.com', 'Travel accessories brand known for its iconic Weekender bag and bestselling suitcases, with thousands of 5-star reviews. Its Awin merchant profile explicitly recruits social media influencers, bloggers, vloggers and creators and promises a ''generous commission'' on new and return customer sales, but publishes no percentage — and a directory listing instead reports 3% via Impact, so no rate is recorded.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/115877.', 'https://ui.awin.com/merchant-profile/115877', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'BÉIS Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/115877', 'https://ui.awin.com/merchant-profile/115877', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/115877', 'network_profile', 'creator_program', 'The brand''s Awin merchant profile: ''Earn commission on your favorite travel accessories by joining the BÉIS affiliate program... We offer: Generous Commission on new and return customer sales; High converting incentives. We''re particularly interested in: Social Media Influencers, Bloggers, Vloggers, Creators.'' Fast facts: 45-day returns and 60-day validation window, ''Generous commission rate'', and ''Additional partnership opportunities for high converters''. No percentage and no earnings-cap statement are published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/bis-travel/', 'third_party_directory', 'commission_rate_conflict', 'LinkClicky''s program listing instead places BÉIS Travel on Impact at 3% per sale. That conflicts with the brand''s own Awin profile (which publishes no figure), so commission_rate is null and the Awin route — the brand''s own network profile — is the recorded one.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 9, 4, 7, 5, '{"compensation": "The brand publishes no rate on its own profile (''generous commission'' only) and a directory reports 3% via a different network, so no rate is recorded and compensation scores low; no cap statement is published.", "contact_access": "No partnerships email is published on the Awin profile \u2014 creators are told to reach out through the program application.", "credibility": "A major, fast-growing travel accessories brand whose Weekender is a category-defining product, with thousands of 5-star reviews per its profile.", "niche_fit": "Travel bags, weekenders and packing content are staples of travel and lifestyle creator feeds.", "opportunity_availability": "Apply through Awin; the profile promises additional partnership opportunities for high converters, but terms are only shared on application.", "ugc_evidence": "The Awin profile explicitly recruits social media influencers, bloggers, vloggers and creators by name \u2014 direct creator-program evidence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('DELSEY Paris', 'https://www.delsey.com', 'French luggage brand designing suitcases and bags since 1946 — Châtelet Air 2.0, Rempart, Helium DLX, Flânerie and Carrousel collections, plus Jeep and florence by mills co-branded lines. Its Awin affiliate program pays a 5% base commission with custom rates available for top publishers and influencers, a full suite of creative assets, and a published contact email for partnership questions.', 'France', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'affiliates@delsey.com', null, 'https://ui.awin.com/merchant-profile/36622', 'needs_review', null);
