  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'DELSEY Paris Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/36622', 'https://ui.awin.com/merchant-profile/36622', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/36622', 'network_profile', 'affiliate_program', 'The brand''s Awin merchant profile: ''As a globally recognized French luggage brand with over 75 years of design heritage...'' Program benefits: ''5% base commission through AWIN; Custom rates for top publishers and influencers; Access to seasonal discounts and exclusive offers; Regular creative and product updates; Real-time tracking and reporting tools.'' And: ''For questions or to explore custom partnerships, contact: affiliates@delsey.com''. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/advertiser-terms/36622', 'network_profile', 'affiliate_program', 'The program''s Awin terms confirm the structure: default commission 5% per sale, custom rates may be available for high-performing affiliates based on volume, conversion or exclusive partnerships; commission paid only on valid, non-returned, tracked sales; payments processed monthly via AWIN with a $50 USD minimum payout threshold; bidding on branded keywords is strictly prohibited.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 11, 12, 8, 5, '{"compensation": "A published 5% base commission \u2014 modest, though custom higher rates are offered to top publishers and influencers; no cap statement is published.", "contact_access": "A direct partnerships email (affiliates@delsey.com) is published on the brand''s own Awin profile for questions and custom partnerships.", "credibility": "One of the world''s best-known luggage houses, designing bags in Paris since 1946.", "niche_fit": "Luggage is a staple of travel-creator content \u2014 packing videos, carry-on reviews and gear lists.", "opportunity_availability": "Join through Awin with brand approval; creative assets, seasonal offers and a product range spanning several price tiers are provided.", "ugc_evidence": "The program terms address publishers, influencers and content creators, but the offer is a conventional link-and-banner affiliate program rather than a structured UGC campaign track."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('LEVEL8', 'https://level8cases.com', 'NYC-born luggage and bag brand (''LEVEL8 Cases'') making design-led suitcases — including top-opening Adventure cases and aluminum carry-ons — backed by a limited lifetime warranty and 15,000+ 5-star reviews. Its Awin affiliate program pays 10% commission on products sold with a 45-day attribution period.', 'United States', 'published') returning id into bid;
