  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'LEVEL8 Cases Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/94771', 'https://ui.awin.com/merchant-profile/94771', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/94771', 'network_profile', 'affiliate_program', 'The brand''s Awin merchant profile: ''LEVEL8 is an NYC-born brand for luggage and bag. We exist to bring a leisure and exquisite way of traveling, with suitcases that honored the art of personal presentation and style. We''d love to have you join our affiliate program where you will receive a 10% commission for any products sold.'' Attribution period (cookie length) is 45 days. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 14, 4, 8, 4, '{"compensation": "A published 10% commission on the brand''s own Awin profile with a longer-than-standard 45-day cookie; no cap statement is published.", "contact_access": "No partnerships email is published on the Awin profile \u2014 joining is through the network application.", "credibility": "An established direct-to-consumer luggage brand with 15,000+ 5-star reviews and a limited lifetime warranty, though smaller than the heritage luggage houses.", "niche_fit": "Design-led carry-ons and luggage sets fit packing, travel-gear and carry-on-only creator content.", "opportunity_availability": "Open application through Awin with brand approval.", "ugc_evidence": "A conventional affiliate program profile; creator-specific campaigns or UGC tracks are not evidenced."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Key Nutrients', 'https://keynutrients.com', 'Key Nutrients makes clean, transparent electrolyte and hydration supplements — zero-sugar, zero-calorie electrolyte powders with disclosed dosing, plus collagen, keto and sleep products — and states it has shipped 250,000+ orders with 25,000+ five-star reviews.', 'United States', 'published') returning id into bid;
