  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Rakuten', 15, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://keynutrients.com/pages/affiliate-faq.', 'https://keynutrients.com/pages/become-an-affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Key Nutrients Affiliate Program', 'https://keynutrients.com/pages/become-an-affiliate', 'https://keynutrients.com/pages/affiliate-faq', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://keynutrients.com/pages/affiliate-faq', 'brand_website', 'affiliate_program', 'Key Nutrients'' own Affiliate FAQ states the default commission is 15% for every conversion, rising by monthly sales volume to 20% at $500-$1,000 and 25% at $1,000+, with a 45-day cookie, PayPal payouts, and sign-up open to anyone including social-media-only promoters.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://keynutrients.com/pages/affiliate-faq', 'brand_website', 'commission_cap', 'The same FAQ answers the question ''Is there any cap on the number of referrals I can generate?'' with ''No! Your earning potential is unlimited'' — an explicit unlimited-earnings statement about earning potential on the brand''s own page, which is why commission_cap is recorded as uncapped; the companion program page repeats ''Unlimited Referrals — you will get paid on every sale''. No absolute creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://keynutrients.com/pages/become-an-affiliate', 'brand_website', 'affiliate_program', 'The brand''s Become an Affiliate page routes sign-up through Rakuten LinkShare (signup.linkshare.com), pays by check or direct deposit on the 20th of each month, and summarises the offer as 15-25% on each conversion.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 17, 6, 9, 4, '{"niche_fit": "Electrolyte hydration, collagen and keto supplements are core topics for fitness, wellness and everyday-athlete creators.", "ugc_evidence": "The brand runs a formal affiliate program explicitly welcoming social-media promoters, with creatives and custom URLs.", "compensation": "15% default commission rising to 25% on monthly volume, with earning potential stated as unlimited on the brand''s own FAQ, so the cap is verified uncapped.", "contact_access": "Application runs through the brand''s own affiliate pages and Rakuten; no public partnerships email was usable from the fetched pages.", "opportunity_availability": "Program is open now, free to join, with a 45-day cookie and monthly payouts.", "credibility": "The brand states 250,000+ orders shipped, 25,000+ five-star reviews and a #1 best-seller position on Amazon for its electrolytes."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('UNI KEY Health', 'https://unikeyhealth.com', 'UNI KEY Health is a Hayden, Idaho-based supplement brand selling its products direct to consumers through unikeyhealth.com, with a US-based customer care team and a long-term-trusted-affiliate positioning.', 'United States', 'published') returning id into bid;
