  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'UNI KEY Health Affiliate Program', 'https://unikeyhealth.com/pages/affiliate-program', 'https://unikeyhealth.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://unikeyhealth.com/pages/affiliate-program', 'brand_website', 'affiliate_program', 'UNI KEY Health''s own affiliate page states affiliates earn a 10% commission each time someone orders via their link or coupon code on unikeyhealth.com, the program is built on the UpPromote platform for long-term trusted affiliates, and affiliates get a dashboard with per-order notifications.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://unikeyhealth.com/pages/affiliate-program', 'brand_website', 'commission_cap', 'The same official page carries the heading ''Unlimited Earnings'' directly above ''10% commission on all sales!'' — the explicit unlimited-earnings statement on the brand''s own page is why commission_cap is recorded as uncapped; no absolute creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 14, 9, 8, 3, '{"niche_fit": "Direct-to-consumer supplements fit weight-management, detox and healthy-ageing creator content.", "ugc_evidence": "The brand runs a dedicated affiliate program on UpPromote aimed at long-term trusted affiliates sharing on social channels.", "compensation": "10% commission on all sales with earnings headed ''Unlimited Earnings'' on the brand''s own page, so the cap is verified uncapped.", "contact_access": "The program page publishes a general contact email and a US phone line for its customer care team.", "opportunity_availability": "Application is open now through the brand''s UpPromote application link.", "credibility": "Established direct supplement brand with a published US address and phone support; limited third-party coverage, so credibility is scored conservatively."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Riva', 'https://getrivanutrition.com', 'Riva makes sugar-free, plant-based, Halal-certified gummy supplements — creatine, pre-workout, NAD+ and sleep formulas in full disclosed doses — shipping from its New Jersey facility with free US shipping over $40.', 'United States', 'published') returning id into bid;
