  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Riva Affiliate Program', 'https://affiliates.getrivanutrition.com/', 'https://affiliates.getrivanutrition.com/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliates.getrivanutrition.com/', 'brand_website', 'affiliate_program', 'Riva''s own affiliate page pays 20% commission on a referred customer''s first order and 10% on every reorder for the life of the customer, tracked by discount code rather than cookies, with monthly PayPal payouts, a 15% audience discount, and applications reviewed by a human within a couple of days.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliates.getrivanutrition.com/', 'brand_website', 'commission_cap', 'The page''s ''no cap'' wording (''There''s no cap and no limit on how many people you refer'' and ''No cap on how many people you refer'') is tied to the NUMBER of people referred, not to total earnings, so under the strict standard commission_cap is recorded as unknown rather than uncapped; no absolute creator-count data is published, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 15, 6, 8, 3, '{"niche_fit": "Creatine, pre-workout and sleep gummies are staple products for fitness, strength and daily-energy creators.", "ugc_evidence": "The brand runs its own affiliate program built for creators, coaches and trainers, with brand assets and early formula access.", "compensation": "20% on first orders and 10% on every reorder for the life of the customer; the published no-cap wording covers referral count only, so the earnings cap is unknown.", "contact_access": "Application runs through the brand''s own affiliate site; no public partnerships email was published on the fetched pages.", "opportunity_availability": "Program is open now, free to join, with human review in a couple of days.", "credibility": "Small, newer brand, but with third-party-tested, fully disclosed labels, Halal certification and a US fulfilment facility."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('BariSlim', 'https://barislim.com', 'BariSlim sells bariatric supplements and post-surgery vitamins — multivitamins, iron with vitamin C, calcium citrate, protein supplements and bundles — built for people recovering from weight-loss surgery.', 'United States', 'published') returning id into bid;
