  insert into public.brands (name, website, description, country, status) values ('Farm to Pet', 'https://farmtopettreats.com', 'Chicago-based independent maker of premium single-ingredient treats for dogs and cats, plus antler chews and food toppers, sold through FarmToPetTreats.com. Its Treat Ambassador (Our Pack) program runs through Shopify Collabs and pays creators flat cash commissions on code/link sales.', 'United States', 'published') returning id into bid;
