  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Shopify Collabs', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://farmtopettreats.com/pages/affiliate.', 'https://farmtopettreats.com/pages/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Farm to Pet Treat Ambassador Program — flat $10 new / $2 returning per sale, ''no commission limit'' per official page, via Shopify Collabs (1K+ follower gate)', 'https://farmtopettreats.com/pages/affiliate', 'https://farmtopettreats.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://farmtopettreats.com/pages/affiliate', 'official_site', 'affiliate', 'Farm to Pet''s official Treat Ambassador page fetched in full: accepted ambassadors receive a unique unlimited 10% discount code and link, and ''For every sale that is made using your personalized code or link, you will earn a commission of up to $10! - based on whether the customer is new or returning. There is no commission limit!'' The explicit no-limit statement on the brand''s own program page makes the commission cap UNCAPPED. The pay is a FLAT bounty (not a percentage), so commission_rate is null with the flat structure recorded here and in the terms evidence below.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://farmtopettreats.com/pages/affiliate-program-disclosures', 'official_site', 'affiliate', 'The brand''s official program terms confirm the flat structure exactly: $10.00 on all eligible purchases by NEW customers and $2.00 on purchases by RETURNING customers using the ambassador''s code/link, paid via Shopify Collabs once at least $25.00 in commission is reached; eligibility requires age 18+ and a valid Shopify Collabs account.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://help.farmtopettreats.com/en-US/articles/treat-ambassador-program-259115', 'official_site', 'creator_program', 'The brand''s official help centre states the gate honestly: ambassadors must have an active US-based pet-focused social media presence (Instagram, TikTok, Facebook and/or YouTube) with at least 1K followers, are chosen at the brand''s discretion, and must post at least once per month and share content to the brand''s upload app monthly. The brand''s press page also publishes the program email ourpack@farmtopettreats.com. TikTok Shop and Amazon routes exist as extra channels but the recorded route is the brand''s own Shopify Collabs program.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 14, 13, 7, 4, '{"niche_fit": "Single-ingredient dog and cat treats are a natural, highly demonstrable pet UGC product with an easy taste-test content format", "ugc_evidence": "A dedicated creator ambassador program requiring monthly social posts and content uploads, with a welcome gift and collaborator invites on Instagram", "compensation": "Verified uncapped per the brand''s own page, but the pay itself is a modest flat $10 per new-customer sale and $2 per returning sale", "contact_access": "Published program email (ourpack@farmtopettreats.com) plus the Shopify Collabs application on the official page", "opportunity_availability": "Gated: US-based pet-focused account with at least 1K followers, brand discretion, and monthly posting duties", "credibility": "Established independent Chicago treat maker with full program terms and disclosures published on its own site"}'::jsonb);
