  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://belkin.grin.live/', 'official_site', 'creator_program', 'Belkin''s official Creator Affiliate application page (on its GRIN creator platform) fetched in full: ''Apply below to be a part of Belkin''s Creator Affiliate program. As a creator affiliate, you''ll receive: 10% commission on sales, free product to try, review, and experience, early access to new product releases, exclusive event invites.'' It publishes the affiliate support email globalsocial@belkin.com. The 10% creator rate stated on the brand''s own creator page is the recorded rate. The page makes no earnings-cap statement, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.belkin.com/ca/company/affiliates-2/', 'official_site', 'affiliate', 'Belkin''s official publisher affiliate page fetched in full: affiliates earn a commission based on the product''s sale price, joining is free with no minimum sales requirements, and ''Impact Radius will pay by check, ACH, wire, or PayPal for a percentage of the sales you referred to our site after you have earned $50 in commissions.'' Third-party listings for this separate publisher route conflict (4% / 8% / up to 10%), which is why the recorded rate rests on the creator program''s own published 10%.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 14, 13, 8, 5, '{"niche_fit": "Chargers, MagSafe accessories and audio are everyday-carry tech staples with endless desk-setup, travel and unboxing content angles", "ugc_evidence": "A dedicated creator affiliate track with free product to review, early access and event invites \u2014 separate from the publisher program", "compensation": "10% on sales per the brand''s own creator page; accessories are mid-priced so per-sale dollars are moderate; no cap statement published", "contact_access": "Published affiliate support email (globalsocial@belkin.com) plus creator and Impact applications", "opportunity_availability": "Creator application reviewed by the brand; publisher route is a standard Impact application, free with no sales minimum", "credibility": "Four-decade global accessories brand, now part of Foxconn Interconnect, with both programs documented on its own pages"}'::jsonb);
