  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'DreamCloud Affiliate Program — flat $150 per mattress plus 12% on accessories via Impact', 'https://getlasso.co/affiliate/dreamcloud/', 'https://getlasso.co/affiliate/dreamcloud/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/dreamcloud/', 'listing', 'affiliate', 'Lasso''s DreamCloud listing reports a FLAT $150 per mattress sale with a 180-day cookie. The flat bounty is the core pay; a percentage also applies to accessories (see below), so the percentage is recorded as the rate with the flat structure documented here. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/dreamcloud/', 'listing', 'affiliate', 'LinkClicky''s network-sourced listing records DreamCloud on Impact at ''$150, 12% per sale'' — the $150 flat per mattress plus 12% on accessories (bedding, pillows) — and multiple 2026 roundups (Whop, UpPromote, BrandID) independently agree on the $150 flat / 12% accessories structure via Impact with a ~30-day cookie (cookie figures conflict at 30 vs 180 days and are not recorded). The recorded 12% is the accessories percentage; mattress pay is the flat $150.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 11, 15, 8, 8, 4, '{"niche_fit": "Luxury-hybrid mattresses at a mid-range price are a proven sleep-review category, and the 365-night trial is a strong content hook", "ugc_evidence": "Network program aimed at sleep bloggers and reviewers; no dedicated creator tier published", "compensation": "A predictable flat $150 per mattress plus 12% on accessories \u2014 among the easiest mattress payouts to forecast; no cap statement published", "contact_access": "Application through Impact; no public program email found", "opportunity_availability": "Standard Impact application with brand review (reported ~24 hours)", "credibility": "Part of the Resident group alongside Nectar, with national brand awareness and a long-running program"}'::jsonb);
