  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://purple.com/affiliate-program', 'official_site', 'creator_program', 'Purple''s official affiliate page fetched in full: it runs two tracks — a ''Creator affiliate program'' for individual creators and influencers and a ''Publisher affiliate program'' for reviews and publications — both earning ''a competitive commission'' through a unique attribution link, with performance tracked in Impact and the exact compensation structure sent in the approval email. Gifted product is explored with creators individually. The brand publishes NO rate and no earnings-cap statement on the page, so the cap is unknown and the rate is settled from listings below.', 'verified', now());
