  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'PetSafe Affiliate Program — pet tech and training products, ~8% reported (official program page found only on staging subdomain — needs review)', 'https://staging.petsafe.com/about-us/petsafe-affiliate-program/', 'https://staging.petsafe.com/about-us/petsafe-affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://staging.petsafe.com/about-us/petsafe-affiliate-program/', 'official_site', 'affiliate', 'PetSafe''s affiliate program page was found and fetched ONLY on the brand''s STAGING subdomain (staging.petsafe.com), so this evidence is flagged needs_review per the staging rule. The page states the program is ''perfect for pet parents, influencers and publishers with a strong online presence and loyal following'', lists ideal partners as influencers, content creators, bloggers and publishers (coupon sites and sub-affiliate networks excluded), and sets guidelines including no bidding on PetSafe trademark terms. It publishes no rate and no earnings-cap statement, so the cap is unknown and the rate is settled from listings below.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/petsafe/', 'listing', 'affiliate', 'Lasso''s PetSafe listing reports up to 9.0% commission with a 14-day cookie; a pet-program guide reports 8% with a long cookie, and Commission Factory''s AU listing states 8% on every qualified sale with a 30-day cookie and AUD $100-$150 average order value. The recorded rate is the 8% figure two sources agree on, with the up-to-9% ceiling noted here.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 11, 7, 7, 4, '{"niche_fit": "Feeders, fountains, litter tech and training gear are core demonstrable pet-tech products for review and problem-solution content", "ugc_evidence": "The program page explicitly names influencers and content creators as ideal partners, with a strong-online-presence expectation", "compensation": "Listings agree around 8% (up to 9% reported) on a $100+ average order; short reported cookie windows temper the value", "contact_access": "Program page application route only; no public program email found", "opportunity_availability": "Application-based with brand guidelines; the live (non-staging) program page could not be confirmed, hence the needs_review flag", "credibility": "Three-decade global pet brand within Radio Systems Corporation, though the staging-only program page lowers verification confidence"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Rover', 'https://www.rover.com', 'The world''s largest marketplace for pet care, connecting pet owners with 200,000+ sitters and dog walkers for boarding, dog walking, house sitting, day care and drop-in visits, booked through Rover.com. Its affiliate program for publishers and creators runs through Impact.', 'United States', 'published') returning id into bid;
