  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://getlasso.co/affiliate/rover/.', 'https://getlasso.co/affiliate/rover/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Rover Affiliate Program — pet-sitting marketplace via Impact (published pay conflicts: 15% vs flat per-booking CPA)', 'https://getlasso.co/affiliate/rover/', 'https://getlasso.co/affiliate/rover/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/rover/', 'listing', 'affiliate', 'Lasso''s Rover listing reports 15% per sale with a 30-day cookie via Impact and a $50 payout threshold. A Referly network profile likewise reports up to 15% per sale with a 30-day cookie and monthly payouts. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.magentheme.com/rover-affiliate-program-review-commissions-payouts/', 'listing', 'affiliate', 'Other published accounts conflict on the pay FORM: a detailed program review states Rover actually pays a FLAT CPA per new-customer first booking (low-to-mid two-digit USD, varying by region/campaign), and a pet-program roundup reports $20 per qualified signup / $15 per booking. Because published sources conflict between a 15% percentage and flat per-booking bounties, commission_rate is null with the conflict recorded here; the Impact route is consistent across sources. A separate customer refer-a-friend credit scheme exists and is NOT the recorded route.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 9, 8, 8, 5, '{"niche_fit": "Pet sitting and dog walking is a service every travelling or working pet owner needs \u2014 a natural fit for pet and travel-lifestyle content", "ugc_evidence": "Program open to pet blogs, city guides and social creators on YouTube, Instagram and TikTok per program reviews; no dedicated creator tier published", "compensation": "Published pay conflicts in form (15% of booking vs flat $15-$25 CPA on first bookings only), so no rate is credited until verified in Impact", "contact_access": "Application through Impact; no public program email found", "opportunity_availability": "Standard Impact application with manual review; no minimum traffic threshold disclosed", "credibility": "The world''s largest pet-care marketplace with 200,000+ providers and a long-running network program"}'::jsonb);
